insert into public.holy_sites
  (name, category, diocese, region_province, location, description, history, lat, lng, seo_title, seo_description, emotion_tag)
values
  ('범어 주교좌대성당', '주교좌성당', '대구대교구', '대구', '대구광역시 수성구', '대구대교구의 두 주교좌성당 중 하나로, 2016년 완공된 현대적 건축 양식의 대성당이다.', '대구대교구는 1902년 완공된 계산 주교좌대성당에 이어 2016년 범어 주교좌대성당을 새로 완공하여, 현재 두 개의 주교좌성당을 함께 운영하고 있다. 대구광역시 수성구에 위치하며 현대 건축 양식의 웅장한 규모로 지어졌다. 계산성당이 대구 근대 역사를 상징하는 성당이라면, 범어성당은 대구대교구의 현대적 면모를 보여주는 공간이다.', 35.8581745018635, 128.630635463648, '대구 범어 주교좌대성당', '계산성당과 함께 대구대교구를 대표하는 2016년 완공 현대식 주교좌대성당', '새출발')
  ('비산동 날뫼 순교지', '순교성지', '대구대교구', '대구', '대구광역시 서구 비산동', '대구 서구 비산동에 남아있는 조선시대 처형장 터로, 박해 시기 천주교 신자들이 순교한 것으로 전해지는 사적지이다.', '비산동 날뫼 순교지는 대구광역시 서구 비산동에 위치한 조선시대 처형장 터이다. 대구대교구 종합자료집에 박해시대 순교 사적지의 하나로 기록되어 있다. 구체적인 순교 연대나 순교자 수 등 세부 사실은 문서상 확인되지 않아 추가 조사가 필요하다.', 35.8872751502313, 128.548031933402, '대구 비산동 순교지', '대구 서구 비산동에 남은 조선시대 처형장 터, 박해시대 순교 사적지', '위로')
  ('장대벌 순교지', '순교성지', '대구대교구', '대구', '대구광역시 남구 봉덕동', '대구 남구 봉덕동에 위치한 조선시대 처형장 터로, 대구 지역의 3대 처형장 중 하나로 꼽히는 순교 사적지이다.', '장대벌 순교지는 대구광역시 남구 봉덕동에 있는 조선시대 처형장 터로, 대구 지역의 3대 처형장 중 하나로 전해진다. 박해시대 천주교 신자들의 순교와 관련된 사적지로 대구대교구 자료에 기록되어 있으나, 구체적인 순교 연대와 인원 등 세부 사실은 추가 확인이 필요하다.', 35.8455729454258, 128.597908299005, '대구 장대벌 순교지', '대구 남구 봉덕동, 대구 3대 처형장 중 하나로 꼽히는 순교 사적지', '치유')
  ('퇴강 성당', '성당', '안동교구', '경북', '경상북도 상주시 사벌면', '경북 상주시 사벌면에 위치한 100년이 넘은 근대 건축 성당으로, 경상북도 문화재자료로 지정되어 있다.', '퇴강 성당은 경상북도 상주시 사벌면에 위치한 근대 성당으로, 1900년대 초반에 건축되었다. 경상북도 문화재자료로 지정되어 있으며, 안동교구 내 대표적인 근대 성당 건축물로 꼽힌다.', 36.4663508052293, 128.208579732352, '상주 퇴강성당', '경북 상주 사벌면에 있는 100년 역사의 근대 문화재 성당', '평온')
  ('산토비아조(Santo Viaggio) 순례길', '순례길', '제주교구', '제주', '제주특별자치도 전역 (제주 일주 순례길, 여러 코스로 구성)', '한라산 아래 오름과 바다, 돌담길과 올레길이 어우러진 제주 섬 전체를 잇는 도보 순례길로, 이탈리아어로 ''거룩한 여행''을 뜻하는 산토비아조를 걸으며 제주에 숨어있는 천주교 성지와 자연을 함께 만난다.', '스페인의 산티아고 순례길에서 영감을 받아 조성된 제주교구의 도보 순례 코스로, 제주 곳곳에 흩어진 천주교 성지와 순례지를 잇는다. 순례자는 스탬프를 모아 완주 인증을 받을 수 있으며, 해설사와 동행하는 프로그램도 운영되고 있다. 제주 올레길과 일부 구간이 겹쳐 종교 순례이자 제주의 자연·문화를 걷는 여행으로도 소개된다.', NULL, NULL, '제주 순례길 산토비아조', '한라산과 바다를 잇는 제주 전역의 도보 순례길, 산토비아조에서 신앙과 자연을 함께 걷다', '평온')
  ('김포 성체성지', '역사사적지', '인천교구', '경기', '경기도 김포시 북변로 29-12', '김포본당의 옛 성전 건물을 보존하여 조성한 성체 순례지로, 인천교구 신자들이 성체 신심을 기리며 찾는 곳이다.', '김포 성체성지는 김포본당의 옛 성전 건물을 그대로 보존하여 조성되었다. 인천교구 내에서 성체 신심 순례지로 지정되어 신자들의 순례 발길이 이어지고 있다.', 37.6296433071257, 126.708292293721, '김포 성체성지', '김포본당 옛 성전을 보존한 인천교구의 성체 신심 순례지', '감사')
  ('백령도 성지', '순교성지', '인천교구', '인천', '인천 옹진군 백령면 백령로254번길 66', '서해 최북단 섬 백령도에 자리한 순교 관련 사적지로, 접근이 어려운 섬이라는 지리적 특성 속에서도 신앙을 지켜온 흔적을 전한다.', '백령도 성지는 인천교구 관할의 서해 최북단 섬에 위치한 순교 관련 사적지로 소개된다. 육지와 멀리 떨어진 섬이라는 특수한 지리적 여건 속에서도 천주교 신앙 공동체의 자취가 이어져 왔다.', 37.9727214277367, 124.720017934993, '백령도 성지', '서해 최북단 섬, 백령도에 남은 순교의 흔적을 만나는 성지', '위로')
  ('한덕골 성지', '교우촌', '수원교구', '경기', '경기도 용인시 처인구', '용인시 처인구에 자리한 교우촌 터로, 박해를 피해 산골로 숨어든 신앙 선조들의 공동체 삶을 전하는 곳이다.', '한덕골은 경기도 용인시 처인구 일대에 형성되었던 천주교 신자들의 교우촌으로 전해진다. 문서상 구체적인 조성 연대나 순교 관련 기록은 확인되지 않는다.', 37.2343060386834, 127.201357139725, '한덕골 교우촌', '용인 처인구에 남은 신앙 공동체의 흔적, 한덕골 성지', '평온')
  ('던지실 성지', '순교성지', '수원교구', '경기', '경기도 안성시 금광면', '안성시 금광면에 위치한 교우촌이자 순교 관련 사적지로, 박해기 신앙공동체의 흔적이 남아있는 곳이다.', '던지실은 안성시 금광면 일대에 형성되었던 천주교 교우촌으로, 박해 시기 순교와 관련된 사적지로 소개된다. 문서에는 구체적인 순교자 수나 연대는 기록되어 있지 않다.', 36.9972240459891, 127.317465473336, '던지실 성지', '안성 금광면의 교우촌이자 순교 사적지, 던지실 성지', '위로')
  ('천호성지', '순교성지', '수원교구', '경기', '경기도 광주시 퇴촌면', '광주시 퇴촌면에 위치한 천주교 교우촌이자 순교자를 기리는 사적지로, 같은 이름을 가진 전주교구 천호성지와는 별개의 장소이다.', '천호성지는 경기도 광주시 퇴촌면 일대에 형성되었던 천주교 교우촌으로, 순교자와 관련된 사적지로 소개된다. 전주교구에도 동명의 ''천호성지''가 존재하나 이는 별도의 장소이며, 이 곳은 수원교구 관할이다.', 37.4666662497915, 127.307068858523, '천호성지(경기 광주)', '광주 퇴촌면 교우촌이자 순교자를 기리는 수원교구 천호성지', '위로')
  ('인제 소양로 성당(내면)', '교우촌', '춘천교구', '강원', '강원특별자치도 인제군 남면 빙어마을길 196', '강원도 인제군 산간지역에 자리한 교우촌 계열의 성당으로, 소양강 상류 깊은 산골에 이어져 온 신앙 공동체의 자취를 보여준다.', '이 성당은 자료상 ''교우촌''으로 분류되어 있어, 박해 시대 신자들이 산간 오지에 숨어 신앙 공동체를 이루었던 지역과 연관된 곳으로 소개된다. 인제군 남면 산골에 위치하며, 강원 내륙 지역 천주교 신앙의 흔적을 보여준다. 구체적인 형성 시기와 관련 인물에 대한 기록은 추가 확인이 필요하다.', 37.9987453276566, 128.096904701668, '인제 소양로 성당', '강원 산골 깊은 곳, 인제 교우촌의 자취를 간직한 소양로 성당을 만나보세요.', '평온')
  ('거두리 성당', '교우촌', '춘천교구', '강원', '강원특별자치도 춘천시 동내면 동내로 220', '춘천 동내면에 자리한 초기 교우촌의 흔적을 간직한 성당으로, 춘천 지역 천주교 신앙의 뿌리를 보여준다.', '거두리성당은 자료상 ''초기 교우촌''으로 소개되어 있으며, 춘천시 동내면 일대 신자 공동체의 초기 역사와 관련된 곳으로 꼽힌다. 구체적인 형성 시기와 관련 인물에 대한 기록은 추가 확인이 필요하다.', 37.8483919351352, 127.775083233466, '춘천 거두리성당', '춘천 동내면, 초기 교우촌의 뿌리를 간직한 거두리성당을 소개합니다.', '평온')
  ('죽림동 주교좌 성당', '주교좌성당', '춘천교구', '강원', '강원특별자치도 춘천시 약사고개길 23', '춘천교구의 중심에 자리한 주교좌성당으로, 강원 지역 천주교 신앙 공동체의 구심점 역할을 하고 있다.', '죽림동주교좌성당은 천주교 춘천교구의 주교좌성당으로, 춘천시 약사고개길에 위치한다. 춘천교구는 1939년 경성대목구에서 분리되어 설정되었고 1962년 정식 교구로 승격되었으며, 이후 죽림동성당이 교구청 소재지의 주교좌성당 역할을 맡아왔다.', 37.876777750874, 127.726904499621, '춘천 죽림동주교좌성당', '춘천교구의 중심, 죽림동주교좌성당에서 강원 신앙 공동체의 구심점을 만나보세요.', '새출발')
