-- Visit Holy Korea 성지 시드 데이터 (배치 3: 노션 교구 문서에서 추가한 13곳)
-- 원본: data/research/holy_sites_batch3_notion_import.json
-- 중복 실행에 대비해 (name, location) 유니크 인덱스 기준으로 충돌 시 건너뛴다.

on conflict do nothing;


-- 교구명 표기 통일.
-- 배치 3 원본(노션 문서)은 '대구대교구'처럼 정식 명칭을 쓰지만, 앱의 교구 필터는
-- '대구'처럼 접미사 없는 표기를 기준으로 한다(shared/types/domain.ts 의 DIOCESES).
-- 표기가 어긋나면 해당 성지가 교구 탐색 화면에서 아예 보이지 않는다.
update public.holy_sites
   set diocese = regexp_replace(diocese, '(대)?교구$', '')
 where diocese ~ '(대)?교구$';
